def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The vertical run at the top of each key color gives the bar's rank.
    ranks = {}
    for c in range(w):
        color = grid[0][c]
        if color != 0 and color not in ranks:
            n = 0
            while n < h and grid[n][c] == color:
                n += 1
            ranks[color] = n

    bars = {}
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == 0:
                r += 1
                continue

            start = r
            while r < h and grid[r][c] != 0:
                r += 1

            vals = [grid[i][c] for i in range(start, r)]
            if (len(vals) >= 3 and vals[0] == vals[-1]
                    and vals[1] != vals[0]
                    and all(v == vals[1] for v in vals[1:-1])):
                bars.setdefault(vals[0], []).append((start, c, r))

    for color, rank in ranks.items():
        candidates = sorted(bars.get(color, []), key=lambda bar: (bar[0], bar[1]))
        if 1 <= rank <= len(candidates):
            start, c, end = candidates[rank - 1]
            for rr in range(start + 1, end - 1):
                out[rr][c] = color

    return out
